CREATE TABLE IF NOT EXISTS deployment_risks (id CHAR(36) PRIMARY KEY, node_id CHAR(36) NOT NULL, kind VARCHAR(64) NOT NULL, severity VARCHAR(16) NOT NULL, state VARCHAR(32) NOT NULL, evidence LONGTEXT NOT NULL, confidence VARCHAR(16) NOT NULL, rule_version VARCHAR(32) NOT NULL, resource_fingerprint CHAR(64) NOT NULL, repair_task_id CHAR(36) NULL, missed_scans INT NOT NULL DEFAULT 0, first_seen_at BIGINT NOT NULL, last_seen_at BIGINT NOT NULL, pending_confirmation_at BIGINT NULL, resolved_at BIGINT NULL, updated_at BIGINT NOT NULL, UNIQUE KEY uq_deployment_risk_node_kind(node_id,kind), INDEX idx_deployment_risks_filter(state,node_id,kind,updated_at), CONSTRAINT fk_deployment_risks_node FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- statement
CREATE TABLE IF NOT EXISTS deployment_risk_scans (id CHAR(36) PRIMARY KEY, node_id CHAR(36) NOT NULL, task_id CHAR(36) NULL, status VARCHAR(16) NOT NULL, error_code VARCHAR(64) NOT NULL, finding_count INT NOT NULL, scanned_at BIGINT NOT NULL, INDEX idx_deployment_risk_scans_node(node_id,scanned_at), CONSTRAINT fk_deployment_risk_scans_node FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
